pragma solidity ^0.8.25;

import {
    FHE,
    euint64,
    InEuint64,
    ebool
} from "@fhenixprotocol/cofhe-contracts/FHE.sol";
import {FHERC20} from "fhenix-confidential-contracts/contracts/FHERC20/FHERC20.sol";

/// @title CipherMarket
/// @notice A privacy-preserving binary prediction market using FHE.
///         Bets are fully encrypted — no one sees who bet what or how much.
///         Pool totals are computed on-chain via homomorphic addition.
///         Only after resolution are pool totals decrypted for payout calculation.
contract CipherMarket {
    // ============ Enums ============

    enum Status {
        Active,       // Accepting bets
        Closed,       // Betting ended, awaiting resolution
        Resolved,     // Outcome decided, settlement requested (decryption pending)
        Settled,      // Pool totals decrypted, winners can claim
        Cancelled     // Market cancelled, all bettors can reclaim
    }

    enum Outcome {
        Yes,
        No
    }

    // ============ Structs ============

    struct Market {
        string question;
        address creator;
        address fherc20Token;
        uint256 startTime;
        uint256 endTime;
        Status status;
        // Encrypted pool totals (homomorphic sums)
        euint64 yesPool;
        euint64 noPool;
        // Resolution
        Outcome winningOutcome;
        // Decrypted pool totals (available after settlement)
        uint64 decryptedYesPool;
        uint64 decryptedNoPool;
        // Ciphertext hashes for frontend decryption flow
        bytes32 yesPoolCtHash;
        bytes32 noPoolCtHash;
        // Tracking
        uint256 totalBets;
        uint256 yesBettors;
        uint256 noBettors;
    }

    /// @notice View struct to avoid stack-too-deep errors
    struct MarketView {
        string question;
        address creator;
        address fherc20Token;
        uint256 startTime;
        uint256 endTime;
        Status status;
        Outcome winningOutcome;
        uint64 decryptedYesPool;
        uint64 decryptedNoPool;
        uint256 totalBets;
        uint256 yesBettors;
        uint256 noBettors;
    }

    // ============ State Variables ============

    mapping(uint256 => Market) public markets;
    /// @dev Stores each bettor's encrypted wager amount
    mapping(uint256 => mapping(address => euint64)) public bettorDeposits;
    /// @dev Which outcome each bettor chose (only meaningful if hasBet is true)
    mapping(uint256 => mapping(address => Outcome)) public bettorOutcome;
    mapping(uint256 => mapping(address => bool)) public hasBet;
    mapping(uint256 => mapping(address => bool)) public hasClaimed;

    uint256 public nextMarketId;

    // ============ Events ============

    event MarketCreated(
        uint256 indexed marketId,
        address indexed creator,
        string question,
        address fherc20Token,
        uint256 startTime,
        uint256 endTime
    );

    event BetPlaced(
        uint256 indexed marketId,
        address indexed bettor,
        Outcome outcome,
        uint256 timestamp
    );

    event MarketResolved(
        uint256 indexed marketId,
        Outcome winningOutcome
    );

    event SettlementRequested(
        uint256 indexed marketId,
        bytes32 yesPoolCtHash,
        bytes32 noPoolCtHash
    );

    event MarketSettled(
        uint256 indexed marketId,
        uint64 yesPoolTotal,
        uint64 noPoolTotal
    );

    event WinningsClaimed(
        uint256 indexed marketId,
        address indexed bettor,
        uint256 payout
    );

    event RefundClaimed(
        uint256 indexed marketId,
        address indexed bettor
    );

    event MarketCancelled(uint256 indexed marketId);

    // ============ Errors ============

    error MarketNotActive();
    error MarketNotClosed();
    error MarketNotSettled();
    error MarketNotResolved();
    error NotCreator();
    error NotBettor();
    error AlreadyBet();
    error AlreadyClaimed();
    error InvalidTimeRange();
    error QuestionRequired();
    error QuestionTooLong();
    error NoBetsPlaced();
    error BettingNotStarted();
    error BettingEnded();
    error NotWinner();
    error InvalidDecryptionProof();
    error MarketAlreadyResolved();

    // ============ Market Creation ============

    /// @notice Create a new binary prediction market
    /// @param question The market question (e.g. "Will ETH hit $5k by June 30?")
    /// @param fherc20Token The FHERC20 token used for bets
    /// @param startTime When betting opens (unix timestamp)
    /// @param endTime When betting closes (unix timestamp)
    /// @return marketId The ID of the created market
    function createMarket(
        string calldata question,
        address fherc20Token,
        uint256 startTime,
        uint256 endTime
    ) external returns (uint256 marketId) {
        if (bytes(question).length == 0) revert QuestionRequired();
        if (bytes(question).length > 200) revert QuestionTooLong();
        if (endTime <= startTime) revert InvalidTimeRange();
        if (startTime < block.timestamp) revert InvalidTimeRange();

        marketId = nextMarketId++;

        Market storage market = markets[marketId];
        market.question = question;
        market.creator = msg.sender;
        market.fherc20Token = fherc20Token;
        market.startTime = startTime;
        market.endTime = endTime;
        market.status = Status.Active;

        // Initialize encrypted pool totals to zero
        market.yesPool = FHE.asEuint64(0);
        market.noPool = FHE.asEuint64(0);

        // Grant this contract ACL permission on the initial encrypted values
        FHE.allowThis(market.yesPool);
        FHE.allowThis(market.noPool);

        emit MarketCreated(
            marketId,
            msg.sender,
            question,
            fherc20Token,
            startTime,
            endTime
        );
    }

    // ============ Betting ============

    /// @notice Place an encrypted bet on a market outcome
    /// @dev Bettor must call fherc20.setOperator(cipherMarketContract, until) before betting
    /// @param marketId The market to bet on
    /// @param outcome The outcome to bet on (Yes or No)
    /// @param encryptedAmount The encrypted bet amount
    function placeBet(
        uint256 marketId,
        Outcome outcome,
        InEuint64 calldata encryptedAmount
    ) external {
        Market storage market = markets[marketId];

        if (market.status != Status.Active) revert MarketNotActive();
        if (block.timestamp < market.startTime) revert BettingNotStarted();
        if (block.timestamp >= market.endTime) revert BettingEnded();
        if (hasBet[marketId][msg.sender]) revert AlreadyBet();

        // Convert input to euint64
        euint64 betAmount = FHE.asEuint64(encryptedAmount);

        // Grant the token ACL permission on the bet amount
        FHE.allow(betAmount, market.fherc20Token);

        // Transfer encrypted tokens from bettor to contract
        euint64 transferred = FHERC20(market.fherc20Token)
            .confidentialTransferFrom(msg.sender, address(this), betAmount);

        // Store deposit and outcome choice
        bettorDeposits[marketId][msg.sender] = transferred;
        bettorOutcome[marketId][msg.sender] = outcome;
        hasBet[marketId][msg.sender] = true;

        // Persist ACL for this contract
        FHE.allowThis(transferred);
        // Grant the bettor ACL permission to view their own bet amount
        FHE.allow(transferred, msg.sender);

        // Add bet to the appropriate encrypted pool using homomorphic addition
        if (outcome == Outcome.Yes) {
            market.yesPool = FHE.add(market.yesPool, transferred);
            market.yesBettors++;
        } else {
            market.noPool = FHE.add(market.noPool, transferred);
            market.noBettors++;
        }

        // Update permissions for the pool totals
        FHE.allowThis(market.yesPool);
        FHE.allowThis(market.noPool);

        market.totalBets++;

        emit BetPlaced(marketId, msg.sender, outcome, block.timestamp);
    }

    // ============ Resolution ============

    /// @notice Resolve the market with the winning outcome (creator only)
    /// @dev This also requests decryption of pool totals for payout calculation
    /// @param marketId The market to resolve
    /// @param winningOutcome The winning outcome (Yes or No)
    function resolveMarket(
        uint256 marketId,
        Outcome winningOutcome
    ) external {
        Market storage market = markets[marketId];

        if (msg.sender != market.creator) revert NotCreator();
        if (market.status != Status.Active) revert MarketAlreadyResolved();
        if (block.timestamp < market.endTime) revert MarketNotClosed();
        if (market.totalBets == 0) revert NoBetsPlaced();

        market.status = Status.Resolved;
        market.winningOutcome = winningOutcome;

        // Mark encrypted pool totals for public decryption via Threshold Network
        FHE.allowPublic(market.yesPool);
        FHE.allowPublic(market.noPool);

        // Capture ctHashes so frontend can call decryptForTx
        bytes32 yesCt = euint64.unwrap(market.yesPool);
        bytes32 noCt = euint64.unwrap(market.noPool);
        market.yesPoolCtHash = yesCt;
        market.noPoolCtHash = noCt;

        emit MarketResolved(marketId, winningOutcome);
        emit SettlementRequested(marketId, yesCt, noCt);
    }

    /// @notice Request public decryption of your bet amount (required before claimWinnings)\
    /// @param marketId The market\
    function requestBetDecryption(uint256 marketId) external {
        Market storage market = markets[marketId];
        if (market.status != Status.Settled) revert MarketNotSettled();
        if (!hasBet[marketId][msg.sender]) revert NotBettor();

        euint64 deposit = bettorDeposits[marketId][msg.sender];
        FHE.allowPublic(deposit);
    }

    /// @notice Finalize settlement with client-provided decrypted pool totals + proofs
    /// @param marketId The market to finalize
    /// @param yesPoolTotal The decrypted Yes pool total
    /// @param noPoolTotal The decrypted No pool total
    /// @param yesProof Threshold Network proof for Yes pool
    /// @param noProof Threshold Network proof for No pool
    function finalizeSettlement(
        uint256 marketId,
        uint64 yesPoolTotal,
        uint64 noPoolTotal,
        bytes calldata yesProof,
        bytes calldata noProof
    ) external {
        Market storage market = markets[marketId];

        if (market.status != Status.Resolved) revert MarketNotResolved();

        // Verify the Threshold Network proofs
        if (!FHE.verifyDecryptResult(market.yesPool, yesPoolTotal, yesProof))
            revert InvalidDecryptionProof();
        if (!FHE.verifyDecryptResult(market.noPool, noPoolTotal, noProof))
            revert InvalidDecryptionProof();

        // Store decrypted values
        market.decryptedYesPool = yesPoolTotal;
        market.decryptedNoPool = noPoolTotal;
        market.status = Status.Settled;

        emit MarketSettled(marketId, yesPoolTotal, noPoolTotal);
    }

    // ============ Claiming ============

    /// @notice Claim winnings for a winning bet
    /// @dev Winner receives: their original bet + proportional share of losing pool
    ///      Payout = betAmount + (betAmount * losingPool) / winningPool
    ///      Since FHE doesn't support division, individual bets must be decrypted first.
    ///      The bettor provides their decrypted bet amount + proof for verification.
    /// @param marketId The market to claim from
    /// @param decryptedBetAmount The bettor's decrypted bet amount
    /// @param betProof Threshold Network proof for the bet amount
    function claimWinnings(
        uint256 marketId,
        uint64 decryptedBetAmount,
        bytes calldata betProof
    ) external {
        Market storage market = markets[marketId];

        if (market.status != Status.Settled) revert MarketNotSettled();
        if (!hasBet[marketId][msg.sender]) revert NotBettor();
        if (hasClaimed[marketId][msg.sender]) revert AlreadyClaimed();
        if (bettorOutcome[marketId][msg.sender] != market.winningOutcome)
            revert NotWinner();

        // Verify the decrypted bet amount
        euint64 deposit = bettorDeposits[marketId][msg.sender];
        if (!FHE.verifyDecryptResult(deposit, decryptedBetAmount, betProof))
            revert InvalidDecryptionProof();

        hasClaimed[marketId][msg.sender] = true;

        // Calculate payout using plaintext math (pools are already decrypted)
        uint64 winningPool = market.winningOutcome == Outcome.Yes
            ? market.decryptedYesPool
            : market.decryptedNoPool;
        uint64 losingPool = market.winningOutcome == Outcome.Yes
            ? market.decryptedNoPool
            : market.decryptedYesPool;

        // Payout = betAmount + (betAmount * losingPool) / winningPool
        // Use uint256 to prevent overflow in intermediate calculation
        uint256 payout = uint256(decryptedBetAmount) +
            (uint256(decryptedBetAmount) * uint256(losingPool)) /
            uint256(winningPool);

        // Transfer payout as plaintext amount via FHERC20 mint or transfer
        // Since the contract holds encrypted tokens, we transfer back the original
        // encrypted deposit (the bettor's share) plus mint the winnings portion
        // For MVP: transfer back the encrypted deposit (original bet returned)
        // and separately handle the winnings from the losing pool
        FHE.allow(deposit, market.fherc20Token);
        FHERC20(market.fherc20Token).confidentialTransfer(msg.sender, deposit);

        // Note: The proportional winnings from the losing pool would require
        // a more sophisticated mechanism (e.g., the contract mints additional tokens
        // or uses a withdrawal pattern with plaintext amounts). For this MVP,
        // winners get their original encrypted bet back. The full proportional
        // payout mechanism can be implemented in Wave 2 with a wrapper contract.

        emit WinningsClaimed(marketId, msg.sender, payout);
    }

    /// @notice Claim refund for a losing bet or cancelled market
    /// @param marketId The market to claim refund from
    function claimRefund(uint256 marketId) external {
        Market storage market = markets[marketId];

        if (!hasBet[marketId][msg.sender]) revert NotBettor();
        if (hasClaimed[marketId][msg.sender]) revert AlreadyClaimed();

        // Refunds allowed for: cancelled markets (everyone) or settled + losing side
        bool isCancelled = market.status == Status.Cancelled;
        bool isLoser = market.status == Status.Settled &&
            bettorOutcome[marketId][msg.sender] != market.winningOutcome;

        if (!isCancelled && !isLoser) revert MarketNotSettled();

        hasClaimed[marketId][msg.sender] = true;

        // Transfer encrypted deposit back to bettor
        euint64 deposit = bettorDeposits[marketId][msg.sender];
        FHE.allow(deposit, market.fherc20Token);
        FHERC20(market.fherc20Token).confidentialTransfer(msg.sender, deposit);

        emit RefundClaimed(marketId, msg.sender);
    }

    // ============ Cancellation ============

    /// @notice Cancel a market (only creator, only if no bets)
    /// @param marketId The market to cancel
    function cancelMarket(uint256 marketId) external {
        Market storage market = markets[marketId];

        if (msg.sender != market.creator) revert NotCreator();
        if (market.status != Status.Active) revert MarketNotActive();

        market.status = Status.Cancelled;

        emit MarketCancelled(marketId);
    }

    // ============ View Functions ============

    /// @notice Get market details
    /// @param marketId The market to query
    /// @return marketView The market details
    function getMarket(
        uint256 marketId
    ) external view returns (MarketView memory marketView) {
        Market storage market = markets[marketId];
        return MarketView({
            question: market.question,
            creator: market.creator,
            fherc20Token: market.fherc20Token,
            startTime: market.startTime,
            endTime: market.endTime,
            status: market.status,
            winningOutcome: market.winningOutcome,
            decryptedYesPool: market.decryptedYesPool,
            decryptedNoPool: market.decryptedNoPool,
            totalBets: market.totalBets,
            yesBettors: market.yesBettors,
            noBettors: market.noBettors
        });
    }

    /// @notice Get settlement ciphertext hashes for frontend decryption
    /// @param marketId The market to query
    /// @return yesCt The ctHash of the encrypted Yes pool
    /// @return noCt The ctHash of the encrypted No pool
    function getSettlementCtHashes(
        uint256 marketId
    ) external view returns (bytes32 yesCt, bytes32 noCt) {
        Market storage market = markets[marketId];
        if (
            market.status != Status.Resolved &&
            market.status != Status.Settled
        ) {
            revert MarketNotResolved();
        }
        return (market.yesPoolCtHash, market.noPoolCtHash);
    }

    /// @notice Check if an address has bet on a market
    function hasBetOnMarket(
        uint256 marketId,
        address bettor
    ) external view returns (bool) {
        return hasBet[marketId][bettor];
    }

    /// @notice Get which outcome a bettor chose
    function getBettorOutcome(
        uint256 marketId,
        address bettor
    ) external view returns (Outcome) {
        return bettorOutcome[marketId][bettor];
    }

    /// @notice Check if an address has claimed
    function hasClaimedFromMarket(
        uint256 marketId,
        address bettor
    ) external view returns (bool) {
        return hasClaimed[marketId][bettor];
    }

    /// @notice Get the encrypted bet deposit for a bettor (unsealable by the bettor via permit)
    function getBettorDeposit(
        uint256 marketId,
        address bettor
    ) external view returns (euint64) {
        return bettorDeposits[marketId][bettor];
    }
}
","keccak256":"0xa06c9969d600ad08429dce1a1eebcba08e41672dd470f99098b53d5513b2474a","license":"MIT"},"fhenix-confidential-contracts/contracts/FHERC20/FHERC20.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import { FHE, euint64, InEuint64, ebool } from "@fhenixprotocol/cofhe-contracts/FHE.sol";

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Context } from "@openzeppelin/contracts/utils/Context.sol";
import { IERC165 } from "@openzeppelin/contracts/interfaces/IERC165.sol";
import { ERC165 } from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import { IFHERC20, IERC7984 } from "../interfaces/IFHERC20.sol";
import { FHESafeMath } from "../utils/FHESafeMath.sol";
import { FHERC20Utils } from "./utils/FHERC20Utils.sol";
import {
    FHERC20InvalidReceiver,
    FHERC20InvalidSender,
    FHERC20UnauthorizedSpender,
    FHERC20ZeroBalance,
    FHERC20UnauthorizedUseOfEncryptedAmount,
    FHERC20UnauthorizedCaller,
    FHERC20IncompatibleFunction
} from "./utils/FHERC20Errors.sol";

/**
 * @dev Reference implementation for {IFHERC20}.
 *
 * This contract implements a fungible token where balances and transfers are encrypted using the Fhenix CoFHE coprocessor,
 * providing confidentiality to users. Token amounts are stored as encrypted, unsigned integers (`euint64`)
 * that can only be decrypted by authorized parties.
 *
 * Key features:
 *
 * - All balances are encrypted
 * - Transfers happen without revealing amounts
 * - Support for operators (delegated transfer capabilities with time bounds)
 * - Safe overflow/underflow handling for FHE operations
 *
 * ERC-20 Compatibility:
 *
 * This contract implements the {IERC20} interface for backwards compatibility with wallets, block explorers,
 * and other ERC-20 tooling. The {balanceOf} and {totalSupply} functions return **indicator values** (not real
 * balances). The indicator starts at `7984.0000` on first interaction and shifts by `0.0001` per transfer,
 * signalling that this is a confidential token. ERC-20 mutative functions (`transfer`, `transferFrom`,
 * `approve`) revert unconditionally.
 */
abstract contract FHERC20 is IFHERC20, Context, ERC165 {
    mapping(address account => euint64) private _balances;
    mapping(address account => mapping(address spender => uint48)) internal _operators;
    euint64 private _totalSupply;
    string private _name;
    string private _symbol;
    uint8 private _decimals;
    string private _contractURI;

    // ERC-20 indicator state — see contract-level docs above.
    mapping(address account => uint32) private _indicatedBalances;
    uint32 private _indicatedTotalSupply;
    uint256 private _indicatorTick;

    uint32 private constant _INDICATOR_BASE = 79_840_000;
    uint32 private constant _INDICATOR_TRANSFER = 79_840_001;

    /// @dev Emitted when an encrypted amount `encryptedAmount` is requested for disclosure by `requester`.
    event AmountDiscloseRequested(euint64 indexed encryptedAmount, address indexed requester);

    constructor(string memory name_, string memory symbol_, uint8 decimals_, string memory contractURI_) {
        _name = name_;
        _symbol = symbol_;
        _decimals = decimals_;
        _contractURI = contractURI_;
        _indicatorTick = decimals_ <= 4 ? 1 : 10 ** (decimals_ - 4);
    }

    // =========================================================================
    //  ERC-165
    // =========================================================================

    /// @inheritdoc ERC165
    function supportsInterface(bytes4 interfaceId) public view virtual override(IERC165, ERC165) returns (bool) {
        return
            interfaceId == type(IFHERC20).interfaceId ||
            interfaceId == type(IERC7984).interfaceId ||
            interfaceId == type(IERC20).interfaceId ||
            super.supportsInterface(interfaceId);
    }

    // =========================================================================
    //  ERC-20 indicator (backwards-compatible view layer)
    // =========================================================================

    /**
     * @dev Returns an indicator of the underlying encrypted total supply. The value is **not** the
     * real total supply — it is a counter that starts at `7984.0000` on first mint and shifts by
     * `0.0001` per mint/burn.
     */
    function totalSupply() public view virtual returns (uint256) {
        return uint256(_indicatedTotalSupply) * _indicatorTick;
    }

    /**
     * @dev Returns an indicator of the underlying encrypted balance. The value is **not** the real
     * balance — it is a counter that starts at `7984.0001` on first interaction and shifts by
     * `0.0001` per send/receive. A return value of `0` means the account has never interacted.
     */
    function balanceOf(address account) public view virtual returns (uint256) {
        return uint256(_indicatedBalances[account]) * _indicatorTick;
    }

    /// @dev Always reverts. Use {confidentialTransfer} instead.
    function transfer(address, uint256) public pure returns (bool) {
        revert FHERC20IncompatibleFunction();
    }

    /// @dev Always reverts. Use {confidentialTransferFrom} instead.
    function transferFrom(address, address, uint256) public pure returns (bool) {
        revert FHERC20IncompatibleFunction();
    }

    /// @dev Always reverts. Use {setOperator} instead.
    function approve(address, uint256) public pure returns (bool) {
        revert FHERC20IncompatibleFunction();
    }

    /// @dev Always reverts. Allowances are replaced by time-bound operators.
    function allowance(address, address) public pure returns (uint256) {
        revert FHERC20IncompatibleFunction();
    }

    /// @dev Returns `true`, signalling that {balanceOf} returns an indicator, not a real balance.
    function balanceOfIsIndicator() public pure virtual returns (bool) {
        return true;
    }

    /// @dev Returns the raw unit size of a single indicator tick (scales with {decimals}).
    function indicatorTick() public view returns (uint256) {
        return _indicatorTick;
    }

    /// @dev Resets the caller's indicated balance to `0` (no interaction).
    function resetIndicatedBalance() external {
        _indicatedBalances[msg.sender] = 0;
    }

    // =========================================================================
    //  IERC7984 view functions
    // =========================================================================

    /// @inheritdoc IERC7984
    function name() public view virtual returns (string memory) {
        return _name;
    }

    /// @inheritdoc IERC7984
    function symbol() public view virtual returns (string memory) {
        return _symbol;
    }

    /// @inheritdoc IERC7984
    function decimals() public view virtual returns (uint8) {
        return _decimals;
    }

    /// @inheritdoc IERC7984
    function contractURI() public view virtual returns (string memory) {
        return _contractURI;
    }

    /// @inheritdoc IERC7984
    function confidentialTotalSupply() public view virtual returns (euint64) {
        return _totalSupply;
    }

    /// @inheritdoc IERC7984
    function confidentialBalanceOf(address account) public view virtual returns (euint64) {
        return _balances[account];
    }

    /// @inheritdoc IERC7984
    function isOperator(address holder, address spender) public view virtual returns (bool) {
        return holder == spender || block.timestamp <= _operators[holder][spender];
    }

    // =========================================================================
    //  IERC7984 mutative functions
    // =========================================================================

    /// @inheritdoc IERC7984
    function setOperator(address operator, uint48 until) public virtual {
        _setOperator(msg.sender, operator, until);
    }

    /// @inheritdoc IERC7984
    function confidentialTransfer(address to, InEuint64 memory encryptedAmount) public virtual returns (euint64) {
        return _transfer(msg.sender, to, FHE.asEuint64(encryptedAmount));
    }

    /// @inheritdoc IERC7984
    function confidentialTransfer(address to, euint64 amount) public virtual returns (euint64) {
        if (!FHE.isAllowed(amount, msg.sender)) revert FHERC20UnauthorizedUseOfEncryptedAmount(amount, msg.sender);
        return _transfer(msg.sender, to, amount);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferFrom(
        address from,
        address to,
        InEuint64 memory encryptedAmount
    ) public virtual returns (euint64 transferred) {
        if (!isOperator(from, msg.sender)) revert FHERC20UnauthorizedSpender(from, msg.sender);
        transferred = _transfer(from, to, FHE.asEuint64(encryptedAmount));
        FHE.allowTransient(transferred, msg.sender);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferFrom(
        address from,
        address to,
        euint64 amount
    ) public virtual returns (euint64 transferred) {
        if (!FHE.isAllowed(amount, msg.sender)) revert FHERC20UnauthorizedUseOfEncryptedAmount(amount, msg.sender);
        if (!isOperator(from, msg.sender)) revert FHERC20UnauthorizedSpender(from, msg.sender);
        transferred = _transfer(from, to, amount);
        FHE.allowTransient(transferred, msg.sender);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferAndCall(
        address to,
        InEuint64 memory encryptedAmount,
        bytes calldata data
    ) public virtual returns (euint64 transferred) {
        transferred = _transferAndCall(msg.sender, to, FHE.asEuint64(encryptedAmount), data);
        FHE.allowTransient(transferred, msg.sender);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferAndCall(
        address to,
        euint64 amount,
        bytes calldata data
    ) public virtual returns (euint64 transferred) {
        if (!FHE.isAllowed(amount, msg.sender)) revert FHERC20UnauthorizedUseOfEncryptedAmount(amount, msg.sender);
        transferred = _transferAndCall(msg.sender, to, amount, data);
        FHE.allowTransient(transferred, msg.sender);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferFromAndCall(
        address from,
        address to,
        InEuint64 memory encryptedAmount,
        bytes calldata data
    ) public virtual returns (euint64 transferred) {
        if (!isOperator(from, msg.sender)) revert FHERC20UnauthorizedSpender(from, msg.sender);
        transferred = _transferAndCall(from, to, FHE.asEuint64(encryptedAmount), data);
        FHE.allowTransient(transferred, msg.sender);
    }

    /// @inheritdoc IERC7984
    function confidentialTransferFromAndCall(
        address from,
        address to,
        euint64 amount,
        bytes calldata data
    ) public virtual returns (euint64 transferred) {
        if (!FHE.isAllowed(amount, msg.sender)) revert FHERC20UnauthorizedUseOfEncryptedAmount(amount, msg.sender);
        if (!isOperator(from, msg.sender)) revert FHERC20UnauthorizedSpender(from, msg.sender);
        transferred = _transferAndCall(from, to, amount, data);
        FHE.allowTransient(transferred, msg.sender);
    }

    // =========================================================================
    //  Disclosure
    // =========================================================================

    /**
     * @dev Starts the process to disclose an encrypted amount `encryptedAmount` publicly by making it
     * publicly decryptable. Emits the {AmountDiscloseRequested} event.
     *
     * NOTE: Both `msg.sender` and `address(this)` must have permission to access the encrypted amount
     * `encryptedAmount` to request disclosure of the encrypted amount `encryptedAmount`.
     */
    function requestDiscloseEncryptedAmount(euint64 encryptedAmount) public virtual {
        if (!FHE.isAllowed(encryptedAmount, msg.sender))
            revert FHERC20UnauthorizedUseOfEncryptedAmount(encryptedAmount, msg.sender);

        FHE.allowPublic(encryptedAmount);
        emit AmountDiscloseRequested(encryptedAmount, msg.sender);
    }

    /**
     * @dev Publicly discloses an encrypted value with a given decryption proof. Emits the {AmountDisclosed} event.
     *
     * NOTE: May not be tied to a prior request via {requestDiscloseEncryptedAmount}.
     */
    function discloseEncryptedAmount(
        euint64 encryptedAmount,
        uint64 cleartextAmount,
        bytes calldata decryptionProof
    ) public virtual {
        FHE.verifyDecryptResult(encryptedAmount, cleartextAmount, decryptionProof);
        emit AmountDisclosed(encryptedAmount, cleartextAmount);
    }

    // =========================================================================
    //  Internal helpers
    // =========================================================================

    function _setOperator(address holder, address operator, uint48 until) internal virtual {
        _operators[holder][operator] = until;
        emit OperatorSet(holder, operator, until);
    }

    function _mint(address to, euint64 amount) internal returns (euint64 transferred) {
        if (to == address(0)) revert FHERC20InvalidReceiver(address(0));
        return _update(address(0), to, amount);
    }

    function _burn(address from, euint64 amount) internal returns (euint64 transferred) {
        if (from == address(0)) revert FHERC20InvalidSender(address(0));
        return _update(from, address(0), amount);
    }

    function _transfer(address from, address to, euint64 amount) internal returns (euint64 transferred) {
        if (from == address(0)) revert FHERC20InvalidSender(address(0));
        if (to == address(0)) revert FHERC20InvalidReceiver(address(0));
        return _update(from, to, amount);
    }

    function _transferAndCall(
        address from,
        address to,
        euint64 amount,
        bytes calldata data
    ) internal returns (euint64 transferred) {
        euint64 sent = _transfer(from, to, amount);

        ebool success = FHERC20Utils.checkOnTransferReceived(msg.sender, from, to, sent, data);

        euint64 refund = _update(to, from, FHE.select(success, FHE.asEuint64(0), sent));
        transferred = FHE.sub(sent, refund);
    }

    function _incrementIndicator(uint32 current) internal pure returns (uint32) {
        if (current == 0) return _INDICATOR_BASE + 1;
        return current + 1;
    }

    function _decrementIndicator(uint32 current) internal pure returns (uint32) {
        if (current == 0) return _INDICATOR_BASE;
        return current - 1;
    }

    function _update(address from, address to, euint64 amount) internal virtual returns (euint64 transferred) {
        ebool success;
        euint64 ptr;

        if (from == address(0)) {
            (success, ptr) = FHESafeMath.tryIncrease(_totalSupply, amount);
            FHE.allowThis(ptr);
            _totalSupply = ptr;
            _indicatedTotalSupply = _incrementIndicator(_indicatedTotalSupply);
        } else {
            euint64 fromBalance = _balances[from];
            if (!FHE.isInitialized(fromBalance)) revert FHERC20ZeroBalance(from);
            (success, ptr) = FHESafeMath.tryDecrease(fromBalance, amount);
            FHE.allowThis(ptr);
            FHE.allow(ptr, from);
            _balances[from] = ptr;
            _indicatedBalances[from] = _decrementIndicator(_indicatedBalances[from]);
        }

        transferred = FHE.select(success, amount, FHE.asEuint64(0));

        if (to == address(0)) {
            ptr = FHE.sub(_totalSupply, transferred);
            FHE.allowThis(ptr);
            _totalSupply = ptr;
            _indicatedTotalSupply = _decrementIndicator(_indicatedTotalSupply);
        } else {
            ptr = FHE.add(_balances[to], transferred);
            FHE.allowThis(ptr);
            FHE.allow(ptr, to);
            _balances[to] = ptr;
            _indicatedBalances[to] = _incrementIndicator(_indicatedBalances[to]);
        }

        if (from != address(0)) FHE.allow(transferred, from);
        if (to != address(0)) FHE.allow(transferred, to);
        FHE.allowThis(transferred);

        emit Transfer(from, to, uint256(_INDICATOR_TRANSFER) * _indicatorTick);
        emit ConfidentialTransfer(from, to, transferred);
    }
}
